#include <stdio.h>

int main() {
    int n;
    double max_sale = 0.0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        double sale;
        scanf("%lf", &sale);
        if (sale > max_sale) {
            max_sale = sale;
        }
    }
    printf("Venta maxima: %.1f\n", max_sale);
    return 0;
}

#include <stdio.h>

int main() {
    int n;
    int count = 0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        double sale;
        scanf("%lf", &sale);
        if (sale > 1000.0) {
            count++;
        }
    }
    printf("Ventas superiores a 1000: %d\n", count);
    return 0;
}
